{
  "description": "The creature is a single quadrupedal animal shown in right-facing profile that combines the body of a brown bear with the exoskeleton and horn of a rhinoceros beetle. Its entire body except the back is covered in dense, long, shaggy brown fur that is lighter tan on the muzzle and lower sides, with a bear-like head, four thick sturdy limbs ending in clawed paws, and no visible wings or tail. A large, highly glossy, dark reddish-brown beetle carapace sits flush on its dorsal side from the back of the neck to the rump, and a single large glossy dark curved horn projects upward and backward from the center of its forehead.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head with dense brown fur, a paler tan muzzle, a large black nose at the tip, small dark brown eyes on the sides, and a closed mouth",
      "where": "at the anterior end of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "single large glossy dark brown to black horn that curves upward and backward, with two small pointed notches on its posterior edge and a shiny reflective surface",
      "where": "arising from the center of the forehead on top of the head"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in short brown fur",
      "where": "on top of the head behind the horn, one slightly behind the other in profile"
    },
    {
      "part": "legs",
      "looks_like": "four thick, columnar, heavily furred brown legs with long shaggy hair, two forelegs under the chest and two hindlegs under the hips",
      "where": "under the torso, supporting the body on the ground"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with dense fur and five long light tan claws visible on each paw",
      "where": "at the distal ends of the four legs in contact with the ground"
    },
    {
      "part": "shell",
      "looks_like": "large glossy dark reddish-brown beetle elytra forming a domed oval shield with fine longitudinal ridges, scattered small pits, and bright white reflective highlights",
      "where": "covering the entire dorsal back from behind the shoulders to the rump, sitting on top of the fur"
    },
    {
      "part": "plates",
      "looks_like": "a large glossy dark pronotal shield with a forward-pointing tip over the shoulders and a row of small overlapping marginal plates with circular holes along the lower edge of the shell, all with the same glossy pitted surface as the shell",
      "where": "the pronotal plate covers the shoulders and base of neck directly behind the head, the marginal plates run along the ventral edge of the elytra on the sides of the body"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 0
}
